Template.memoCodeAtTop:
p.SoftCode, li.SoftCode, div.SoftCode
	{mso-style-name:SoftCode;
	margin-top:0in;
	margin-right:0in;
	margin-bottom:0in;
	margin-left:.05in;
	margin-bottom:.0001pt;
	text-indent:-.05in;
	mso-line-height-alt:6.0pt;
	mso-pagination:widow-orphan lines-together;
	page-break-after:avoid;
	mso-list:l0 level1 lfo1;
	mso-hyphenate:none;
	tab-stops:list .05in left 1.5in 2.0in 2.5in 3.0in 3.5in 4.0in 4.5in 5.0in;
	background:#F3F3F3;
	border:none;
	mso-border-top-alt:solid windowtext .25pt;
	mso-border-left-alt:solid windowtext .25pt;
	mso-border-bottom-alt:solid windowtext .25pt;
	padding:0in;
	mso-padding-alt:4.0pt 0in 4.0pt 0in;
	mso-element:frame;
	mso-element-frame-hspace:9.35pt;
	mso-element-frame-vspace:9.35pt;
	mso-element-wrap:no-wrap-beside;
	mso-element-anchor-horizontal:margin;
	mso-element-top:.05pt;
	mso-height-rule:exactly;
	font-size:9.0pt;
	mso-bidi-font-size:10.0pt;
	font-family:"Courier New";
	mso-fareast-font-family:"Times New Roman";
	mso-bidi-font-family:"Times New Roman";}

~~'
  ~~Set OutputPath=%%ChoosePath::F:\Data\Programming 2000\HTML Help 2 Output%%
  ~~Set Stylesheet Page Directoryname=%%Output Path%%stylesheet.css
~~'
  ~~Set Server URL=http://www.gjt.org/
  ~~Set Base URL=%%Server URL%%pkgdoc/
  ~~Set Base Source URL=%%Server URL%%servlets/JCVSlet/show/gjt/
~~'
  ~~Kill %%Stylesheet Page Directoryname%%
  ~~Filename %%Stylesheet Page Directoryname%%
/* Javadoc style sheet */

/* Define colors, fonts and other style attributes here to override the defaults  */

/* Page background color */
body { background-color: #FFFFFF }

/* Table colors */
#TableHeadingColor     { background: #CCCCFF } /* Dark mauve */
#TableSubHeadingColor  { background: #EEEEFF } /* Light mauve */
#TableRowColor         { background: #FFFFFF } /* White */

/* Font used in left-hand frame lists */
#FrameTitleFont   { font-size: normal; font-family: normal }
#FrameHeadingFont { font-size: normal; font-family: normal }
#FrameItemFont    { font-size: normal; font-family: normal }

/* Example of smaller, sans-serif font in frames */
/* #FrameItemFont  { font-size: 10pt; font-family: Helvetica, Arial, sans-serif } */

/* Navigation bar fonts and colors */
#NavBarCell1    { background-color:#EEEEFF;}/* Light mauve */
#NavBarCell1Rev { background-color:#00008B;}/* Dark Blue */
#NavBarFont1    { font-family: Arial, Helvetica, sans-serif; color:#000000;}
#NavBarFont1Rev { font-family: Arial, Helvetica, sans-serif; color:#FFFFFF;}

#NavBarCell2    { font-family: Arial, Helvetica, sans-serif; background-color:#FFFFFF;}
#NavBarCell3    { font-family: Arial, Helvetica, sans-serif; background-color:#FFFFFF;}
